IDS = ["YM-044","YM-045","YM-047","YM-048","YM-049","YM-050","YM-052","YM-053","YM-054","YM-055","YM-057","YM-058","YM-059","YM-060","YM-062","YM-063","YM-064","YM-065","YM-067","YM-068","YM-069","YM-070","YY-006","YY-010","YY-011","YY-012","YY-013","YY-014","YY-015","YY-016","YY-017","YY-018","YY-019","YY-020","YY-021","YY-022","YY-023","YY-024","YY2-001","YY2-002"]
assert len(P) == 40, len(P)
by = {p["case_id"]: p for p in P}
assert set(by) == set(IDS)
# segmented write: 4 batches of 10, assert after each batch
total = 0
for b in range(4):
    chunk = IDS[b*10:(b+1)*10]
    for cid in chunk:
        data = json.dumps(by[cid], ensure_ascii=False, indent=1).encode("utf-8")
        with open(os.path.join(OUT, cid + ".json"), "wb") as f:
            f.write(data)
        total += len(data)
    for cid in chunk:
        with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
            d = json.load(f)
        assert d["case_id"] == cid
        assert set(d) == {"case_id","prediction_text","basis","confidence","trigger"}, d.keys()
        assert 0 <= d["confidence"] <= 1
        tr = d["trigger"]
        assert all(isinstance(tr[k], bool) for k in ("changed_main","reserve_used","disputed"))
        assert isinstance(tr["reason"], str)
    print("batch", b+1, "ok", len(chunk))
# final per-id verification
cm = sum(1 for p in P if p["trigger"]["changed_main"])
ru = sum(1 for p in P if p["trigger"]["reserve_used"])
di = sum(1 for p in P if p["trigger"]["disputed"])
print("written", len(P), "bytes", total, "triggers", cm, ru, di)
